METIN = [
 M('Nahl 16/44 — beyân görevi', 'Kur’an’ı açıklama görevinin Hz. Peygamber’e verildiğini bildiren âyet; nebevî tefsirin dayanağı.', 'وَأَنْزَلْنَا إِلَيْكَ الذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ وَلَعَلَّهُمْ يَتَفَكَّرُونَ', 'en-Nahl 16/44'),
 M('Sâd 38/29 — tedebbür', 'Kur’an’ın indiriliş amacının âyetler üzerinde derin düşünmek olduğu; tefsirin gerekçesi.', 'كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُولُو الْأَلْبَابِ', 'Sâd 38/29'),
 M('İbn Abbâs — tefsirin dört yönü', 'Tefsirin bilinme derecesine göre en eski tasnifi: dilden bilinen, herkesin bilmesi gereken, âlimlerin bildiği ve yalnız Allah’ın bildiği.', 'التَّفْسِيرُ عَلَى أَرْبَعَةِ أَوْجُهٍ: وَجْهٌ تَعْرِفُهُ الْعَرَبُ مِنْ كَلَامِهَا، وَتَفْسِيرٌ لَا يُعْذَرُ أَحَدٌ بِجَهَالَتِهِ، وَتَفْسِيرٌ يَعْلَمُهُ الْعُلَمَاءُ، وَتَفْسِيرٌ لَا يَعْلَمُهُ إِلَّا اللَّهُ', 'Taberî, Câmiu’l-beyân, Mukaddime'),
 M('Mücâhid — İbn Abbâs’a arz', 'Tâbiîn döneminde tefsirin nasıl öğrenildiğini gösteren rivayet: âyet âyet durup sorarak.', 'عَرَضْتُ الْمُصْحَفَ عَلَى ابْنِ عَبَّاسٍ ثَلَاثَ عَرَضَاتٍ مِنْ فَاتِحَتِهِ إِلَى خَاتِمَتِهِ، أُوقِفُهُ عِنْدَ كُلِّ آيَةٍ مِنْهُ وَأَسْأَلُهُ عَنْهَا', 'Taberî, Câmiu’l-beyân, Mukaddime'),
 M('Bilgisizce tefsir uyarısı', 'Re’y-i mezmûmun yasaklandığına delil getirilen hadis.', 'مَنْ قَالَ فِي الْقُرْآنِ بِغَيْرِ عِلْمٍ فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ', 'Tirmizî, Tefsîr 1'),
 M('Zemahşerî — müfessirin iki ilmi', 'Keşşâf mukaddimesinden: Kur’an’ın inceliklerine ancak meânî ve beyân ilimlerinde derinleşen kişi dalabilir.', 'لَا يَتَصَدَّى مِنْهُمْ أَحَدٌ لِسُلُوكِ تِلْكَ الطَّرَائِقِ، وَلَا يَغُوصُ عَلَى شَيْءٍ مِنْ تِلْكَ الْحَقَائِقِ، إِلَّا رَجُلٌ قَدْ بَرَعَ فِي عِلْمَيْنِ مُخْتَصَّيْنِ بِالْقُرْآنِ، وَهُمَا عِلْمُ الْمَعَانِي وَعِلْمُ الْبَيَانِ', 'Zemahşerî, el-Keşşâf, Mukaddime')]
